"""Author PRE_A1-U10 only, including its eight-task checkpoint."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][9]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(9,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U10.UNDERSTAND';A='PRE_A1.U10.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('pain','fr:pain:bread','du pain','хлеб (в просьбе: хлеба)','дю пэ́(н)',ex('Du pain, s’il vous plaît.','Хлеба, пожалуйста.','дю пэ(н), силь ву плэ́'),1,[rev('pain-meaning',fr('Du pain','дю пэ́(н)'),['Сыр','Хлеб','Кофе'],1,'Назван хлеб в сочетании для просьбы.','Правильный смысл — хлеб, а не сыр или кофе.'),rev('pain-use',ru('К учебному завтраку нужен хлеб. Какое сочетание выбрать для просьбы?'),[fr('Du fromage','дю фрома́ж'),fr('Un café','э(н) кафэ́'),fr('Du pain','дю пэ́(н)')],2,'Сочетание соответствует хлебу.','Нужен хлеб; сыр и кофе обозначают другие продукты.')])
addword('fromage','fr:fromage:cheese','du fromage','сыр (в просьбе: сыра)','дю фрома́ж',ex('Du fromage, s’il vous plaît.','Сыра, пожалуйста.','дю фромаж, силь ву плэ́'),1,[rev('fromage-meaning',fr('Du fromage','дю фрома́ж'),['Сыр','Чай','Хлеб'],0,'Назван сыр в сочетании для просьбы.','Это сыр, а не чай или хлеб.'),rev('fromage-use',ru('В условии к завтраку нужен сыр. Какое сочетание соответствует выбору?'),[fr('Du pain','дю пэ́(н)'),fr('Du fromage','дю фрома́ж'),fr('Un thé','э(н) тэ́')],1,'Выбран сыр.','Нужен сыр; хлеб и чай изменят выбор.')])
FRUITS=[('pomme','apple','une pomme','яблоко','юн по́м'),('banane','banana','une banane','банан','юн бана́н'),('orange','orange-fruit','une orange','апельсин','юн ора́(н)ж')]
for index,(i,key,f,r,p) in enumerate(FRUITS):
 others=[x for x in FRUITS if x[0]!=i]
 meanings=[x[3] for x in others];meanings.insert(index,r)
 applications=[fr(x[2],x[4]) for x in others];applications.insert((index+1)%3,fr(f,p))
 addword(i,'fr:'+i+':'+key,f,r,p,ex(f.capitalize()+', s’il vous plaît.',r.capitalize()+', пожалуйста.',p+', силь ву плэ́'),2,[rev(i+'-meaning',fr(f,p),meanings,index,f'Это {r}.',f'Правильный смысл — «{r}»; другие варианты называют другие фрукты.'),rev(i+'-use',ru(f'Для учебного завтрака по условию нужен именно {r}. Какое сочетание выбрать?'),applications,(index+1)%3,'Выбран нужный по условию фрукт.',f'Нужен фрукт «{r}»; остальные варианты изменят выбор.')])
addword('petit-dejeuner','fr:petit-dejeuner:breakfast','le petit déjeuner','завтрак','лё пёти дэжёнэ́',ex('Le petit déjeuner : du pain, un café.','Завтрак: хлеб, кофе.','лё пёти дэжёнэ : дю пэ(н), э(н) кафэ́'),3,[rev('petit-dejeuner-meaning',fr('Le petit déjeuner','лё пёти дэжёнэ́'),['Кофе','Завтрак','Сыр'],1,'Это название утреннего приёма пищи.','Правильный смысл — завтрак, а не отдельный напиток или продукт.'),rev('petit-dejeuner-use',ru('Нужна подпись для всего утреннего приёма пищи, а не одного продукта. Что выбрать?'),[fr('Du pain','дю пэ́(н)'),fr('Un café','э(н) кафэ́'),fr('Le petit déjeuner','лё пёти дэжёнэ́')],2,'Подпись называет весь завтрак.','Нужно название приёма пищи; хлеб и кофе — только отдельные позиции.')])
addword('croissant','fr:croissant:pastry','un croissant','круассан','э(н) круаса́(н)',ex('Un croissant, s’il vous plaît.','Круассан, пожалуйста.','э(н) круаса(н), силь ву плэ́'),3,[rev('croissant-meaning',fr('Un croissant','э(н) круаса́(н)'),['Круассан','Хлеб','Сыр'],0,'Назван круассан.','Это круассан, а не хлеб в общем или сыр.'),rev('croissant-use',ru('В учебном заказе нужен круассан. Какое сочетание выбрать?'),[fr('Du fromage','дю фрома́ж'),fr('Un croissant','э(н) круаса́(н)'),fr('Du pain','дю пэ́(н)')],1,'Выбрано сочетание для круассана.','Нужен круассан; два других сочетания называют другие позиции.')])
addword('jaime','fr:jaime:food-liking','j’aime','Мне нравится (о еде)','жэ́м',ex('J’aime le pain.','Мне нравится хлеб.','жэм лё пэ́(н)'),4,[rev('jaime-meaning',fr('J’aime le pain.','жэм лё пэ́(н)'),['Мне не нравится хлеб.','Мне бы хотелось хлеба.','Мне нравится хлеб.'],2,'Говорящий сообщает положительное отношение к продукту.','Это «мне нравится», а не отрицание или просьба получить хлеб.'),rev('jaime-use',ru('По условию персонажу нравится сыр. Какую реплику выбрать?'),[fr('J’aime le fromage.','жэм лё фрома́ж'),fr('Je n’aime pas le fromage.','жё нэм па лё фрома́ж'),fr('Je voudrais du fromage.','жё вудрэ дю фрома́ж')],0,'Реплика сообщает, что продукт нравится.','Нужно положительное предпочтение; отрицание и просьба имеют другой смысл.')])
addword('je-naime-pas','fr:je-naime-pas:food-dislike','je n’aime pas','Мне не нравится (о еде)','жё нэм па́',ex('Je n’aime pas le fromage.','Мне не нравится сыр.','жё нэм па лё фрома́ж'),4,[rev('je-naime-pas-meaning',fr('Je n’aime pas le fromage.','жё нэм па лё фрома́ж'),['Мне не нравится сыр.','Мне нравится сыр.','Мне бы хотелось сыра.'],0,'Говорящий сообщает отрицательное отношение к продукту.','Здесь продукт не нравится; это не положительное предпочтение и не просьба.'),rev('je-naime-pas-use',ru('По условию персонажу не нравится хлеб. Какую реплику выбрать?'),[fr('Je voudrais du pain.','жё вудрэ дю пэ́(н)'),fr('Je n’aime pas le pain.','жё нэм па лё пэ́(н)'),fr('J’aime le pain.','жэм лё пэ́(н)')],1,'Реплика сообщает, что хлеб не нравится.','Нужно отрицательное предпочтение; просьба и положительное отношение не подходят.')])
addword('et','fr:et:and','et','и (соединяет названия)','э',ex('Du pain et du fromage.','Хлеб и сыр.','дю пэ(н) э дю фрома́ж'),4,[rev('et-meaning',fr('Du pain et du fromage.','дю пэ(н) э дю фрома́ж'),['Только хлеб','Хлеб и сыр','Только сыр'],1,'Соединительное слово связывает две позиции.','Названы обе позиции, а не только одна.'),rev('et-use',ru('Нужно соединить названия хлеба и сыра в одном перечне. Какое слово означает «и»?'),[fr('et','э'),fr('pas','па'),fr('un','э́(н)')],0,'Слово соединяет два названия.','Для соединения нужен смысл «и»; отрицательная часть и артикль не выполняют эту роль.')])

s=start(1,'Узнавайте хлеб и сыр в коротких репликах и просите нужный продукт к учебному завтраку. Повторите знакомый напиток и температуру.',['pain','fromage','cafe','the','chaud','froid','je-voudrais','eau','sil-vous-plait'])
