order(s,[A],['je-voudrais','croissant','sil-vous-plait'],[],'Попросите круассан к учебному завтраку. Начните с вежливой рамки и закончите словом «пожалуйста».',[('Je voudrais','жё вудрэ́'),('un croissant,','э(н) круаса́(н)'),('s’il vous plaît.','силь ву плэ́')],'Je voudrais un croissant, s’il vous plaît.','жё вудрэ э(н) круаса(н), силь ву плэ́.','Целое сочетание продукта стоит после начала просьбы.','Поставьте вежливую рамку первой, затем продукт целой карточкой и формулу вежливости.')
page(s,[('Название приёма пищи',['Завтрак — общее название, после которого в учебном меню перечислены отдельные продукты и напитки. Учитывайте именно указанные позиции, а не привычный состав завтрака.'],[W['petit-dejeuner']['example']]),('Круассан в заказе',['Название продукта учим вместе с артиклем. Его можно подставить после уже знакомого начала вежливой просьбы.'],[W['croissant']['example'],ex('Je voudrais un croissant.','Я бы хотел(а) круассан.','жё вудрэ э(н) круаса́(н)')]),('Продукт и напиток — разные позиции',['Если по условию нужен напиток, продукт не заменяет его. В одном упражнении могут возвращаться знакомые хлеб, сыр, чай и кофе.'],[ex('Le petit déjeuner : du pain, un thé.','Завтрак: хлеб, чай.','лё пёти дэжёнэ : дю пэ(н), э(н) тэ́')])])

