choose(s,'reading',['PRE_A1.U07.UNDERSTAND'],['pomme','vert','rouge','bleu'],['vert'],'Вспомните показанную форму цвета. Какого цвета яблоко?',fr('Une pomme verte.','юн пом вэ́рт.'),['Красного','Зелёного','Синего'],1,'Яблоко названо зелёным.','Нужен зелёный цвет; красный и синий в записи отсутствуют.')
intro(s,2,'Два готовых начала: j’aime — «мне нравится», je n’aime pas — «мне не нравится». О продукте в целом используем показанные образцы: J’aime le pain. — «Мне нравится хлеб»; Je n’aime pas le fromage. — «Мне не нравится сыр». Это предпочтение, а не просьба получить порцию.',['jaime','je-naime-pas'],[('j’aime','жэ́м'),('je n’aime pas','жё нэм па́'),('J’aime le pain.','жэм лё пэ́(н)'),('Je n’aime pas le fromage.','жё нэм па лё фрома́ж')],('J’aime le pain. Je n’aime pas le fromage.','жэм лё пэ́(н). жё нэм па лё фрома́ж.'))
choose(s,'vocabulary',[A],['jaime','je-naime-pas','je-voudrais','pain'],['jaime'],'По условию персонажу нравится хлеб. Какая реплика сообщает именно предпочтение?',ru('Не заменяйте предпочтение просьбой.'),[fr('Je n’aime pas le pain.','жё нэм па лё пэ́(н).'),fr('J’aime le pain.','жэм лё пэ́(н).'),fr('Je voudrais du pain.','жё вудрэ дю пэ́(н).')],1,'Реплика сообщает положительное предпочтение.','Нужно «мне нравится хлеб»; отрицание и просьба передают другой смысл.')
