choose(s,'reading',[A],['jaime','je-naime-pas','pain','fromage'],['jaime','pain'],'Какой продукт нравится по этим репликам?',fr('J’aime le pain. Je n’aime pas le fromage.','жэм лё пэ́(н). жё нэм па лё фрома́ж.'),['Хлеб','Сыр','Оба продукта'],0,'Хлеб нравится, а о сыре сказано обратное.','Нравится хлеб. Отрицание во второй реплике не позволяет выбрать оба продукта.')
intro(s,5,'Для предпочтения яблок в целом покажем ещё один образец: J’aime les pommes. — «Мне нравятся яблоки». С тем же сочетанием можно сказать Je n’aime pas les pommes. — «Мне не нравятся яблоки». Учим эти примеры, не заменяя ими форму просьбы об одном яблоке.',['jaime','pomme'],[('J’aime les pommes.','жэм лэ по́м'),('Je n’aime pas les pommes.','жё нэм па лэ по́м')],('J’aime les pommes. Je n’aime pas les pommes.','жэм лэ по́м. жё нэм па лэ по́м.'))
choose(s,'vocabulary',[A],['jaime','je-naime-pas','je-voudrais','pomme'],['jaime'],'По условию персонажу нравятся яблоки. Какую реплику выбрать?',ru('Нужно положительное предпочтение, а не заказ одного фрукта.'),[fr('Je voudrais une pomme.','жё вудрэ юн по́м.'),fr('Je n’aime pas les pommes.','жё нэм па лэ по́м.'),fr('J’aime les pommes.','жэм лэ по́м.')],2,'Реплика сообщает, что яблоки нравятся.','Нужно положительное предпочтение; просьба об одном яблоке и отрицание имеют другой смысл.')
intro(s,6,'Чтобы соединить два названия, используем et — «и». Например, J’aime le pain et le fromage. — «Мне нравятся хлеб и сыр». В этой отдельной реплике положительное отношение относится к обоим продуктам.',['et'],[('et','э'),('J’aime le pain et le fromage.','жэм лё пэ(н) э лё фрома́ж')],('J’aime le pain et le fromage.','жэм лё пэ(н) э лё фрома́ж.'))
choose(s,'reading',[A],['jaime','et','pain','fromage'],['et'],'Какие продукты нравятся в этой отдельной реплике?',fr('J’aime le pain et le fromage.','жэм лё пэ(н) э лё фрома́ж.'),['Только сыр','Хлеб и сыр','Только хлеб'],1,'Соединительное слово относит предпочтение к обеим названным позициям.','Нравятся оба продукта, а не только один из них.')
order(s,[A],['jaime','et','pain','fromage'],[],'Соберите сообщение «Мне нравятся хлеб и сыр». Начните с положительного предпочтения, первым назовите хлеб, затем сыр.',[('J’aime','жэ́м'),('le pain','лё пэ́(н)'),('et le fromage.','э лё фрома́ж')],'J’aime le pain et le fromage.','жэм лё пэ(н) э лё фрома́ж.','Начало предпочтения соединено с двумя названиями в указанном порядке.','Поставьте положительное начало первым, затем хлеб и часть со словом «и» перед сыром.')
page(s,[('Предпочтение отличается от просьбы',['Сообщение о том, что продукт нравится, не является заказом. В противоположном образце отрицательная часть сообщает, что продукт не нравится.'],[W['jaime']['example'],W['je-naime-pas']['example'],ex('Je voudrais du pain.','Мне бы хотелось хлеба.','жё вудрэ дю пэ́(н)')]),('Продукт в целом',['Для общего предпочтения показаны сочетания с хлебом, сыром и яблоками. Учите эти целые примеры; правило не переносится автоматически на любую новую конструкцию.'],[ex('J’aime les pommes.','Мне нравятся яблоки.','жэм лэ по́м'),ex('Je n’aime pas les pommes.','Мне не нравятся яблоки.','жё нэм па лэ по́м')]),('Соединяем два названия',['Соединительное слово со значением «и» связывает две позиции. Условия упражнений задают предпочтение персонажа, поэтому ответ не зависит от личных вкусов учащегося.'],[ex('J’aime le pain et le fromage.','Мне нравятся хлеб и сыр.','жэм лё пэ(н) э лё фрома́ж')])])

